import {env} from 'cloudflare:workers';
import {academicSchema,createAcademicDemo,migrateData,studentData,validateAcademic,initialAdminHash,type AcademicData,type Actor} from '../shared/academic';
import {equalText,hashPassword,verifyPassword,tokenHash} from '../shared/password';
import {z} from 'zod';
export class PortalError extends Error{constructor(message:string,public status=400){super(message);}}
type Account={id:string;username:string;role:'admin'|'student';student_id:string|null;password_hash:string|null;must_change:number};
type State={data:AcademicData;revision:number;owner_id:string};
const DB=()=>{if(!env.DB)throw new PortalError('The academic database is unavailable.',503);return env.DB;};
export const response=(data:unknown,status=200,headers:Record<string,string>={})=>Response.json(data,{status,headers:{'Cache-Control':'private, no-store',...headers}});
export function failure(e:unknown){if(e instanceof z.ZodError)return response({error:'Check all required fields, registration numbers, and numeric values.'},400);if(e instanceof PortalError)return response({error:e.message},e.status);console.error(e);return response({error:e instanceof Error?e.message:'The operation could not be completed.'},400);}
export function checkOrigin(request:Request){const origin=request.headers.get('origin');if(origin&&new URL(request.url).origin!==origin)throw new PortalError('Invalid request origin.',403);}
export async function bodyOf(request:Request){if(Number(request.headers.get('content-length')||0)>8_000_000)throw new PortalError('The request is too large.',413);return await request.json() as Record<string,unknown>;}
export async function loadState():Promise<State>{const db=DB();let row=await db.prepare('SELECT * FROM workspaces WHERE id = ?').bind('main').first<{owner_id:string;payload:string;revision:number}>();if(!row){await db.prepare('INSERT OR IGNORE INTO workspaces (id,owner_id,payload,revision,updated_at) VALUES (?,?,?,?,?)').bind('main','portal-owner',JSON.stringify(createAcademicDemo()),1,new Date().toISOString()).run();row=await db.prepare('SELECT * FROM workspaces WHERE id = ?').bind('main').first<{owner_id:string;payload:string;revision:number}>();}if(!row)throw new PortalError('Workspace initialization failed.',500);const raw=JSON.parse(row.payload);const data=migrateData(raw);if(raw.version!==2){const result=await db.prepare('UPDATE workspaces SET payload=?, revision=revision+1, updated_at=? WHERE id=? AND revision=?').bind(JSON.stringify(data),new Date().toISOString(),'main',row.revision).run();if(!result.meta.changes)return loadState();row.revision++;}
 await db.prepare('INSERT OR IGNORE INTO portal_accounts (id,username,role,student_id,password_hash,must_change) VALUES (?,?,?,?,?,?)').bind('administrator','admin','admin',null,initialAdminHash,1).run();
 const existing=await db.prepare('SELECT student_id FROM portal_accounts WHERE student_id IS NOT NULL').all<{student_id:string}>();const found=new Set(existing.results.map(a=>a.student_id));const missing=data.students.filter(s=>!found.has(s.id));if(missing.length)await db.batch(missing.map(s=>db.prepare('INSERT OR IGNORE INTO portal_accounts (id,username,role,student_id,password_hash,must_change) VALUES (?,?,?,?,?,?)').bind('u-'+s.id,s.registration.toLowerCase(),'student',s.id,null,1)));
 return {data,revision:row.revision,owner_id:row.owner_id};}
const cookieName='ist_portal_session';
function cookieToken(request:Request){return (request.headers.get('cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith(cookieName+'='))?.slice(cookieName.length+1)||'';}
function cookie(request:Request,token:string,clear=false){return `${cookieName}=${token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${clear?0:43200}${new URL(request.url).protocol==='https:'?'; Secure':''}`;}
async function accountFromRequest(request:Request){const token=cookieToken(request);if(!token)return null;return DB().prepare('SELECT a.* FROM portal_accounts a INNER JOIN portal_sessions s ON s.account_id=a.id WHERE s.token_hash=? AND s.expires_at>?').bind(tokenHash(token),Date.now()).first<Account>();}
function actorOf(a:Account,data:AcademicData):Actor{const s=data.students.find(s=>s.id===a.student_id);if(a.role==='student'&&!s)throw new PortalError('Student account is not linked to a record.',403);return {id:a.id,username:a.username,role:a.role,studentId:a.student_id,name:a.role==='admin'?'Administrator':s!.name,mustChange:!!a.must_change};}
export async function requireAccount(request:Request,state:State,allowPasswordChange=false){const account=await accountFromRequest(request);if(!account)throw new PortalError('Please sign in to continue.',401);const actor=actorOf(account,state.data);if(actor.mustChange&&!allowPasswordChange)throw new PortalError('Set a new password before continuing.',428);return {account,actor};}
async function issueSession(a:Account,request:Request){const token=Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');await DB().prepare('INSERT INTO portal_sessions (token_hash,account_id,expires_at) VALUES (?,?,?)').bind(tokenHash(token),a.id,Date.now()+43200000).run();return cookie(request,token);}
async function validPassword(a:Account,password:string,data:AcademicData){return a.password_hash?verifyPassword(password,a.password_hash):equalText(password,data.students.find(s=>s.id===a.student_id)?.registration||'\u0000');}
export async function authGet(request:Request){const state=await loadState();const a=await accountFromRequest(request);return response({actor:a?actorOf(a,state.data):null,settings:{institution:state.data.settings.institution,subtitle:state.data.settings.subtitle}});}
export async function authPost(request:Request){checkOrigin(request);const state=await loadState();const body=await bodyOf(request);const action=body.action;
 if(action==='logout'){const token=cookieToken(request);if(token)await DB().prepare('DELETE FROM portal_sessions WHERE token_hash=?').bind(tokenHash(token)).run();return response({ok:true},200,{'Set-Cookie':cookie(request,'',true)});}
 if(action==='login'){const {username,password,role}=z.object({username:z.string().trim().min(1).max(80),password:z.string().min(1).max(128),role:z.enum(['admin','student'])}).parse(body);const normalized=username.toLowerCase();const attemptKey=tokenHash(normalized+'|'+role+'|'+(request.headers.get('cf-connecting-ip')||'local'));const attempts=await DB().prepare('SELECT count,window_start FROM portal_login_attempts WHERE key=?').bind(attemptKey).first<{count:number;window_start:number}>();if(attempts&&Date.now()-attempts.window_start<900000&&attempts.count>=5)throw new PortalError('Too many attempts. Try again in 15 minutes.',429);const a=await DB().prepare('SELECT * FROM portal_accounts WHERE username=? AND role=?').bind(normalized,role).first<Account>();if(!a||!(await validPassword(a,password,state.data))){const start=attempts&&Date.now()-attempts.window_start<900000?attempts.window_start:Date.now();const count=start===attempts?.window_start?attempts.count+1:1;await DB().prepare('INSERT INTO portal_login_attempts (key,count,window_start) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET count=excluded.count,window_start=excluded.window_start').bind(attemptKey,count,start).run();throw new PortalError('Invalid username or password.',401);}await DB().prepare('DELETE FROM portal_login_attempts WHERE key=?').bind(attemptKey).run();return response({actor:actorOf(a,state.data)},200,{'Set-Cookie':await issueSession(a,request)});}
 const {account,actor}=await requireAccount(request,state,true);
 if(action==='password'){const fields=z.object({currentPassword:z.string().min(1).max(128),newPassword:z.string().min(6).max(128)}).parse(body);if(!(await validPassword(account,fields.currentPassword,state.data)))throw new PortalError('Your current password is incorrect.',400);if(equalText(fields.currentPassword,fields.newPassword)||equalText(actor.username,fields.newPassword.toLowerCase()))throw new PortalError('Choose a new password different from your current password and username.');const hash=await hashPassword(fields.newPassword);await DB().batch([DB().prepare('UPDATE portal_accounts SET password_hash=?,must_change=0 WHERE id=?').bind(hash,account.id),DB().prepare('DELETE FROM portal_sessions WHERE account_id=?').bind(account.id)]);account.password_hash=hash;account.must_change=0;return response({actor:actorOf(account,state.data)},200,{'Set-Cookie':await issueSession(account,request)});}
 if(action==='reset-student'){if(actor.role!=='admin'||actor.mustChange)throw new PortalError('Administrator access required.',403);const sid=z.string().parse(body.studentId);const s=state.data.students.find(s=>s.id===sid);if(!s)throw new PortalError('Student not found.',404);await DB().batch([DB().prepare('UPDATE portal_accounts SET password_hash=NULL,must_change=1 WHERE student_id=?').bind(sid),DB().prepare('DELETE FROM portal_sessions WHERE account_id IN (SELECT id FROM portal_accounts WHERE student_id=?)').bind(sid)]);return response({ok:true});}
 throw new PortalError('Unknown account operation.');}
export async function workspaceGet(request:Request){const state=await loadState();const {actor}=await requireAccount(request,state);return response({data:actor.role==='admin'?state.data:studentData(state.data,actor.studentId!),revision:state.revision,actor});}
export async function workspacePut(request:Request){checkOrigin(request);const state=await loadState();const {actor}=await requireAccount(request,state);if(actor.role!=='admin')throw new PortalError('Administrator access required.',403);const body=await bodyOf(request);if(body.revision!==state.revision)throw new PortalError('Another update was saved. Reload the page before saving again.',409);const data=academicSchema.parse(body.data);validateAcademic(data,state.data);const db=DB();const updates:D1PreparedStatement[]=[];for(const s of data.students){updates.push(db.prepare('INSERT OR IGNORE INTO portal_accounts (id,username,role,student_id,password_hash,must_change) SELECT ?,?,?,?,?,? WHERE (SELECT revision FROM workspaces WHERE id=?)=?').bind('u-'+s.id,s.registration.toLowerCase(),'student',s.id,null,1,'main',state.revision));updates.push(db.prepare('UPDATE portal_accounts SET username=? WHERE student_id=? AND (SELECT revision FROM workspaces WHERE id=?)=?').bind(s.registration.toLowerCase(),s.id,'main',state.revision));}
 updates.push(db.prepare('UPDATE workspaces SET payload=?,revision=revision+1,updated_at=? WHERE id=? AND revision=?').bind(JSON.stringify(data),new Date().toISOString(),'main',state.revision));const results=await db.batch(updates);if(!results[results.length-1].meta.changes)throw new PortalError('Another update was saved. Reload the page before saving again.',409);return response({revision:state.revision+1});}
