const enc=new TextEncoder();const rr=(v:number,n:number)=>(v>>>n)|(v<<(32-n));
export function sha256(input:Uint8Array){const n=Math.ceil((input.length+9)/64)*64,b=new Uint8Array(n);b.set(input);b[input.length]=128;const view=new DataView(b.buffer);view.setUint32(n-4,input.length*8);view.setUint32(n-8,Math.floor(input.length/0x20000000));const h=new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);const w=new Uint32Array(64);for(let offset=0;offset<n;offset+=64){for(let i=0;i<16;i++)w[i]=view.getUint32(offset+i*4);for(let i=16;i<64;i++){const x=w[i-15],y=w[i-2];w[i]=w[i-16]+(rr(x,7)^rr(x,18)^(x>>>3))+w[i-7]+(rr(y,17)^rr(y,19)^(y>>>10));}let [a,c,d,e,f,g,j,k]=h;for(let i=0;i<64;i++){const t1=(k+(rr(f,6)^rr(f,11)^rr(f,25))+((f&g)^(~f&j))+K[i]+w[i])>>>0;const t2=((rr(a,2)^rr(a,13)^rr(a,22))+((a&c)^(a&d)^(c&d)))>>>0;k=j;j=g;g=f;f=(e+t1)>>>0;e=d;d=c;c=a;a=(t1+t2)>>>0;}const vals=[a,c,d,e,f,g,j,k];for(let i=0;i<8;i++)h[i]=(h[i]+vals[i])>>>0;}const out=new Uint8Array(32),v=new DataView(out.buffer);h.forEach((x,i)=>v.setUint32(i*4,x));return out;}
export const hex=(b:Uint8Array)=>Array.from(b,n=>n.toString(16).padStart(2,'0')).join('');
const unhex=(s:string)=>new Uint8Array(s.match(/../g)!.map(v=>parseInt(v,16)));
const concat=(a:Uint8Array,b:Uint8Array)=>{const c=new Uint8Array(a.length+b.length);c.set(a);c.set(b,a.length);return c;};
export const tokenHash=(s:string)=>hex(sha256(enc.encode(s)));
export const equalText=(a:string,b:string)=>{let n=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)n|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return n===0;};
export async function derive(password:string,salt:Uint8Array,iterations:number,forceFallback=false){if(crypto.subtle&&!forceFallback){const key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);return new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:salt as BufferSource,iterations,hash:'SHA-256'},key,256));}let key=enc.encode(password);if(key.length>64)key=sha256(key);const ipad=new Uint8Array(64).fill(0x36),opad=new Uint8Array(64).fill(0x5c);for(let i=0;i<key.length;i++){ipad[i]^=key[i];opad[i]^=key[i];}const hmac=(v:Uint8Array)=>sha256(concat(opad,sha256(concat(ipad,v))));let u=hmac(concat(salt,new Uint8Array([0,0,0,1])));const t=new Uint8Array(u);for(let i=1;i<iterations;i++){u=hmac(u);for(let j=0;j<32;j++)t[j]^=u[j];if(i%2000===0)await new Promise(r=>setTimeout(r,0));}return t;}
export async function hashPassword(password:string){const salt=crypto.getRandomValues(new Uint8Array(16));return `pbkdf2:100000:${hex(salt)}:${hex(await derive(password,salt,100000))}`;}
export async function verifyPassword(password:string,stored:string){const [algorithm,count,salt,expected]=stored.split(':');if(algorithm!=='pbkdf2'||!salt||!expected||Number(count)<1||Number(count)>100000)return false;return equalText(hex(await derive(password,unhex(salt),Number(count))),expected);}
