export type Student = {id:string; roll:string; name:string; email:string; department:string; session:string; semester:number};
export type Course = {id:string; code:string; name:string; department:string; semester:number; credits:number};
export type Mark = {id:string; studentId:string; courseId:string; assignment:number|null; classTest:number|null; midterm:number|null; final:number|null};
export type Band = {min:number; letter:string; point:number};
export type Settings = {institution:string; examOffice:string; assignment:number; classTest:number; midterm:number; final:number; bands:Band[]};
export type Activity = {id:string; text:string; time:string; kind:string};
export type Data = {students:Student[]; courses:Course[]; marks:Mark[]; published:string[]; settings:Settings; activities:Activity[]; demo:boolean};
export const departments = ['Computer Science & Engineering','Electrical & Electronic Engineering','Business Administration'];
export const deptShort = (v:string) => v===departments[0]?'CSE':v===departments[1]?'EEE':v===departments[2]?'BBA':v;
export const semesterName = (n:number) => n+(n===1?'st':n===2?'nd':n===3?'rd':'th')+' semester';
export const publishKey=(session:string,department:string,semester:number)=>[session,department,semester].join('|');
export const components=['assignment','classTest','midterm','final'] as const;
export const componentLabels={assignment:'Assignment',classTest:'Class test',midterm:'Midterm',final:'Final exam'};
export const defaultSettings:Settings={institution:'Greenfield University',examOffice:'Office of the Controller of Examinations',assignment:10,classTest:10,midterm:30,final:50,bands:[{min:80,letter:'A+',point:4},{min:75,letter:'A',point:3.75},{min:70,letter:'A−',point:3.5},{min:65,letter:'B+',point:3.25},{min:60,letter:'B',point:3},{min:55,letter:'B−',point:2.75},{min:50,letter:'C+',point:2.5},{min:45,letter:'C',point:2.25},{min:40,letter:'D',point:2},{min:0,letter:'F',point:0}]};
export const isComplete=(m:Mark|undefined)=>!!m && components.every(k=>m[k]!==null && Number.isFinite(m[k]));
export const totalMark=(m:Mark)=>components.reduce((n,k)=>n+(m[k]??0),0);
export function grade(m:Mark|undefined, settings:Settings){if(!isComplete(m))return {letter:'—',point:0};return [...settings.bands].sort((a,b)=>b.min-a.min).find(b=>totalMark(m!)>=b.min)??{letter:'F',point:0};}
export function semesterStats(data:Data, studentId:string,semester:number){const student=data.students.find(s=>s.id===studentId);const courses=data.courses.filter(c=>c.department===student?.department&&c.semester===semester);let points=0,credits=0,earned=0,complete=0,failed=0;courses.forEach(c=>{const m=data.marks.find(m=>m.studentId===studentId&&m.courseId===c.id);if(isComplete(m)){const g=grade(m,data.settings);points+=g.point*c.credits;credits+=c.credits;complete++;if(g.point>0)earned+=c.credits;else failed++;}});return {gpa:credits?points/credits:0,credits,earned,complete,failed,courses: courses.length, pending:courses.length-complete};}
export function cgpa(data:Data,studentId:string,publishedOnly=false){const s=data.students.find(s=>s.id===studentId);if(!s)return 0;const latest=new Map<string,{c:Course,m:Mark}>();data.courses.filter(c=>c.department===s.department&&c.semester<=s.semester).sort((a,b)=>a.semester-b.semester).forEach(c=>{if(publishedOnly&&!data.published.includes(publishKey(s.session,s.department,c.semester)))return;const m=data.marks.find(m=>m.studentId===s.id&&m.courseId===c.id);if(isComplete(m))latest.set(c.code,{c,m:m!});});let p=0,cr=0;latest.forEach(({c,m})=>{p+=grade(m,data.settings).point*c.credits;cr+=c.credits;});return cr?p/cr:0;}
export function createDemo():Data{
 const names=['Ayesha Rahman','Arif Hasan','Nusrat Jahan','Tanvir Ahmed','Farhana Islam','Rafiul Karim','Mehedi Hasan','Samia Akter','Sadia Afrin','Imran Hossain','Fahim Chowdhury','Tasnia Ahmed','Shakib Rahman','Maliha Khan','Sabbir Hossain','Nabila Islam','Rakib Ahmed','Muntaha Noor','Siam Mahmud','Raisa Tasnim','Abrar Fahad','Sumaiya Khan','Nafis Iqbal','Jannatul Ferdous'];
 const catalog=[['Data Structures','Database Management','Discrete Mathematics','Digital Logic Design','Object-oriented Programming','Engineering Mathematics'],['Circuit Analysis','Electrical Machines','Electronic Devices','Signals & Systems','Control Systems','Engineering Mathematics'],['Financial Accounting','Principles of Marketing','Business Statistics','Business Communication','Organizational Behavior','Microeconomics']];
 const students:Student[]=[];const courses:Course[]=[];const marks:Mark[]=[];const sessions=['2023–2024','2024–2025'];
 departments.forEach((d,di)=>{for(let sem=1;sem<=4;sem++)for(let ci=0;ci<6;ci++)courses.push({id:`c-${di}-${sem}-${ci}`,code:`${deptShort(d)} ${sem}0${ci+1}`,name:catalog[di][(ci+sem-3+6)%6],department:d,semester:sem,credits:ci===3?1.5:3});
 sessions.forEach((session,si)=>{for(let j=0;j<8;j++){const n=di*8+j;const id=`s-${di}-${si}-${j}`;students.push({id,roll:`${si===0?'2023':'2024'}${di+1}${String(j+1).padStart(3,'0')}`,name:names[n],email:names[n].toLowerCase().replace(/ /g,'.')+`${si?'24':''}@student.example.edu`,department:d,session,semester:si===0?3:1});
 courses.filter(c=>c.department===d&&c.semester<=(si===0?3:1)).forEach((c,ci)=>{const base=j===7&&ci===12?34:Math.min(94,69+((j*7+ci*3+di*5)%24));const a=Math.round(base*.1),t=Math.round(base*.1),mid=Math.round(base*.3),f=base-a-t-mid;marks.push({id:`m-${id}-${c.id}`,studentId:id,courseId:c.id,assignment:a,classTest:t,midterm:mid,final:(j===6&&c.semester===3&&ci===17)?null:f});});}});});
 const published:string[]=[];departments.forEach(d=>{for(let sem=1;sem<=2;sem++)published.push(publishKey(sessions[0],d,sem));published.push(publishKey(sessions[1],d,1));});
 return {students,courses,marks,published,settings:defaultSettings,demo:true,activities:[{id:'a1',text:'3rd semester assessment marks imported',time:'2026-10-26T12:00:00Z',kind:'marks'},{id:'a2',text:'2nd semester results published',time:'2026-10-25T12:00:00Z',kind:'publish'},{id:'a3',text:'Academic session 2024–2025 created',time:'2026-10-24T12:00:00Z',kind:'session'}]};
}
